const BASE_ID = 'appvFxwZc9yU8o8pK';
const BRANDS_TABLE = 'tblEkb2WGoh407zEn';
const SCRIPTS_TABLE = 'tbl2D9mapezLKMPg7';

const fields = [
  { table: BRANDS_TABLE, tableName: 'Brands', body: { name: 'ad_account_id', type: 'singleLineText', description: 'Meta ad account ID (e.g. act_921159353090591)' } },
  { table: SCRIPTS_TABLE, tableName: 'Scripts', body: { name: 'meta_ad_name', type: 'singleLineText', description: 'Matched Meta ad name' } },
  { table: SCRIPTS_TABLE, tableName: 'Scripts', body: { name: 'meta_ad_id', type: 'singleLineText', description: 'Meta ad ID for direct lookup' } },
  { table: SCRIPTS_TABLE, tableName: 'Scripts', body: { name: 'ad_spend', type: 'number', options: { precision: 2 }, description: 'Total spend on this scripts ad' } },
  { table: SCRIPTS_TABLE, tableName: 'Scripts', body: { name: 'ad_ctr', type: 'number', options: { precision: 2 }, description: 'Click-through rate percent' } },
  { table: SCRIPTS_TABLE, tableName: 'Scripts', body: { name: 'ad_roas', type: 'number', options: { precision: 2 }, description: 'Return on ad spend' } },
  { table: SCRIPTS_TABLE, tableName: 'Scripts', body: { name: 'ad_impressions', type: 'number', options: { precision: 0 }, description: 'Total impressions' } },
  { table: SCRIPTS_TABLE, tableName: 'Scripts', body: { name: 'performance_tier', type: 'singleSelect', options: { choices: [{ name: 'Top Performer', color: 'greenBright' }, { name: 'Good', color: 'cyanBright' }, { name: 'Average', color: 'yellowBright' }, { name: 'Underperformer', color: 'redBright' }] }, description: 'Performance tier based on ROAS and CTR' } }
];

return fields.map(f => ({ json: { url: `https://api.airtable.com/v0/meta/bases/${BASE_ID}/tables/${f.table}/fields`, bodyJson: JSON.stringify(f.body), tableName: f.tableName, fieldName: f.body.name } }));

const items = $input.all();
const prep = $('Prepare Field Definitions').all();
const results = items.map((item, i) => {
  const meta = prep[i]?.json || {};
  const resp = item.json;
  if (resp.id) return { table: meta.tableName, field: meta.fieldName, status: 'created', fieldId: resp.id };
  if (resp.error) {
    const msg = JSON.stringify(resp.error);
    if (msg.includes('DUPLICATE') || msg.includes('already exists') || msg.includes('duplicate')) return { table: meta.tableName, field: meta.fieldName, status: 'already_exists' };
    return { table: meta.tableName, field: meta.fieldName, status: 'error', error: msg };
  }
  return { table: meta.tableName, field: meta.fieldName, status: 'unknown', raw: JSON.stringify(resp).substring(0, 200) };
});
return [{ json: { results, summary: { created: results.filter(r => r.status === 'created').length, existing: results.filter(r => r.status === 'already_exists').length, errors: results.filter(r => r.status === 'error').length } } }];
